define('core/tokenStore',['lodash', 'core/store'], function (_, store) {
  'use strict';

  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  store = store && Object.prototype.hasOwnProperty.call(store, 'default') ? store['default'] : store;
  var defaultConfig = {
    maxSize: 6,
    tokenTimeLimit: 1000 * 60 * 24,
    store: 'memory'
  };
  function tokenStoreFactory(options) {
    var config = _.defaults(options || {}, defaultConfig);
    var getStoreBackend = () => store.backends[config.store] || store.backends[defaultConfig.store];
    var getStore = () => store('tokenStore.tokens', getStoreBackend());
    return {
      dequeue() {
        return this.getIndex().then(latestIndex => {
          var key = _.first(latestIndex);
          if (!key) {
            return Promise.resolve();
          }
          return getStore().then(storage => storage.getItem(key)).then(token => this.remove(key).then(() => token));
        });
      },
      enqueue(token) {
        if (_.isString(token)) {
          token = {
            value: token,
            receivedAt: Date.now()
          };
        }
        return getStore().then(storage => storage.setItem(token.value, token)).then(updated => {
          if (updated) {
            return this.enforceMaxSize().then(() => true);
          }
          return false;
        });
      },
      getIndex() {
        return this.getTokens().then(tokens => Object.values(tokens).sort((t1, t2) => t1.receivedAt - t2.receivedAt).map(token => token.value));
      },
      has(key) {
        return this.getIndex().then(latestIndex => latestIndex.includes(key));
      },
      remove(key) {
        return this.has(key).then(result => {
          if (result) {
            return getStore().then(storage => storage.removeItem(key));
          }
          return false;
        });
      },
      clear() {
        return getStore().then(storage => storage.clear());
      },
      getTokens() {
        return getStore().then(storage => storage.getItems());
      },
      getSize() {
        return this.getIndex().then(latestIndex => latestIndex.length);
      },
      setMaxSize(size) {
        if (_.isNumber(size) && size > 0 && size !== config.maxSize) {
          config.maxSize = size;
          this.enforceMaxSize();
        }
      },
      enforceMaxSize() {
        return this.getIndex().then(latestIndex => {
          var excess = latestIndex.length - config.maxSize;
          if (excess > 0) {
            var keysToRemove = latestIndex.slice(0, excess);
            return Promise.all(keysToRemove.map(key => this.remove(key)));
          }
          return true;
        });
      },
      checkExpiry(token) {
        var tokenTimeLimit = config.tokenTimeLimit;
        if (tokenTimeLimit > 0 && Date.now() - token.receivedAt > tokenTimeLimit) {
          return this.remove(token.value);
        }
        return Promise.resolve(true);
      },
      expireOldTokens() {
        return this.getTokens().then(tokens => Object.values(tokens).reduce((previousPromise, nextToken) => previousPromise.then(() => this.checkExpiry(nextToken)), Promise.resolve())).then(() => true);
      }
    };
  }
  return tokenStoreFactory;
});
