define('util/httpErrorParser',[],function () {
  'use strict';
  var httpErrorParser = {
    parse: function parse(xhr, options, errorThrown) {
      var msg;
      var json;
      var error;
      try {
        json = JSON.parse(xhr.responseText);
        msg = json.message ? json.message : errorThrown;
      } catch (e) {
        msg = errorThrown;
      }
      error = new Error(msg);
      error.response = xhr;
      error.code = xhr.status;
      error.errorThrown = errorThrown;
      return error;
    }
  };
  return httpErrorParser;
});
